#include <stdio.h>

int j;                                      // file scope: usable from this line to the end of the file

void f(int i) {                             // parameter i: block scope (the body of f)
    int j = 1;                              // block scope: hides the file scope j inside f
    i++;
    printf("\tfunc: i = %d, j = %d\n", i, j);
    for (int i = 0; i < 2; i++) {           // block scope (the loop): hides the parameter i
        int j = 2;                          // block scope (the loop body): hides f's j
        printf("\t\tfor loop, i = %d, j = %d\n", i, j);
    }
    printf("\tfunc: i = %d, j = %d\n", i, j);
}

int k;                                      // file scope, but only from HERE on: f cannot use k

int main(void) {
    printf("main: j = %d\n", j);
    f(100);
    printf("main: j = %d\n", j);
    return 0;
}

