#include <stdio.h>

void visit(void) {
    int a = 0;              // automatic: a new a, set to 0, on every call
    static int s = 0;       // static: one s for the whole run, set to 0 once
    a++;
    s++;
    printf("a = %d, s = %d\n", a, s);
}

int main(void) {
    visit();
    visit();
    visit();
    return 0;
}

#include <stdio.h>

unsigned int count(unsigned int increment) {
    static unsigned int value = 0;           // initialized to 0 exactly once, retains value between calls
    if (increment > 0) {
        // potential overflow bug
        value += increment;
    }
    return value;
}

int main(void) {
    // current value of the counter
    unsigned int c = count(0);
    printf("current count = %u\n", c);
    c = count(1);
    printf("increment, current count = %u\n", c);
    c = count(1);
    printf("increment, current count = %u\n", c);
    c = count(1);
    printf("increment, current count = %u\n", c);
    c = count(0);
    printf("current count = %u\n", c);

    return 0;
}

