#include <stdio.h>

unsigned int sum_of(unsigned int n) {
    unsigned int sum = 0;                   // local: starts at 0 on every call
    for (unsigned int i = 0; i <= n; i++) {
        sum += i;
    }
    return sum;
}

void print_sum(unsigned int n, unsigned int sum) {
    printf("sum_of(%u) = %u\n", n, sum);
}

int main(void) {
    print_sum(10, sum_of(10));
    print_sum(10, sum_of(10));
    return 0;
}

