#include <stdio.h>

int total = 0;                          // global: file scope, static storage

int add(int x) {
    static int calls = 0;               // set to 0 once, before the program starts
    calls++;
    total = total + x;                  // no local total here, so this is the global
    printf("call %d: x = %d, total = %d\n", calls, x, total);
    return calls;
}

int main(void) {
    int total = 100;                    // main's own total: hides the global in main
    add(5);
    int c = add(total);                 // passes main's total, 100
    printf("main: total = %d, c = %d\n", total, c);
    return 0;
}

