#include <stdio.h>

// returns the average of every value it has been given so far
double average_so_far(double x) {
    static double total = 0.0;
    static int count = 0;
    total = total + x;
    count++;
    return total / count;
}

int main(void) {
    printf("%.2f\n", average_so_far(4.0));
    printf("%.2f\n", average_so_far(2.0));
    printf("%.2f\n", average_so_far(9.0));
    printf("%.2f\n", average_so_far(1.0));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// returns x minus the value passed on the previous call; 0 on the first call
int change(int x) {
    static int first = 1;       // 1 until the first call has happened
    static int previous;        // the value from the previous call
    int d = 0;
    if (first == 0) {
        d = x - previous;
    }
    first = 0;
    previous = x;
    return d;
}

int main(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        int x = atoi(argv[i]);
        printf("%d %d\n", x, change(x));
    }
    return 0;
}
